311	inline constexpr bool isBorrowedFieldPair = isBorrowedFieldCallable<Read>
312	    && isBorrowedFieldCallable<Write> && !IsLimits<std::remove_cv_t<Write>>::value
313	    && IsLimits<Limits>::value;
