    checkIntegerScalar<ScalarType::S32, &Scalar::fromS32, std::int32_t>("s32", "-2147483648", "2147483647");
    checkIntegerScalar<ScalarType::S64, &Scalar::fromS64, std::int64_t>("s64", "-9223372036854775808", "9223372036854775807");

